create or replace function clinic_private.valid_dental_record(doc jsonb) returns boolean
language plpgsql immutable strict set search_path='' as $$
declare movement jsonb; installment jsonb;
begin
  if octet_length(doc::text)>40000 then return false; end if;
  if doc ? 'evolucion' then
    if jsonb_typeof(doc->'evolucion') is distinct from 'array' then return false; end if;
    for movement in select value from jsonb_array_elements(doc->'evolucion') loop
      if jsonb_typeof(movement) is distinct from 'object' then return false; end if;
      if movement ? 'abonos' then
        if not extensions.jsonb_matches_schema($schema${"type":"array","maxItems":100,"items":{"type":"object","required":["fecha","cantidad"],"additionalProperties":false,"properties":{
          "fecha":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
          "cantidad":{"type":"string","pattern":"^[0-9]{1,12}(\\.[0-9]{1,2})?$"}}}}$schema$::json,movement->'abonos') then return false; end if;
        for installment in select value from jsonb_array_elements(movement->'abonos') loop
          if (installment->>'cantidad')::numeric<=0 or
            make_date(substring(installment->>'fecha',1,4)::int,substring(installment->>'fecha',6,2)::int,substring(installment->>'fecha',9,2)::int)::text<>installment->>'fecha'
            then return false; end if;
        end loop;
      end if;
    end loop;
  end if;
  return extensions.jsonb_matches_schema($schema${"type":"object","properties":{"id":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},"nombre":{"type":"string","maxLength":160,"pattern":"\\S"},"telefono":{"type":"string","maxLength":120,"pattern":"\\S"},"campos":{"type":"object","properties":{"edad":{"type":"string","pattern":"^[0-9]{1,4}$"},"fecha":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},"direccion":{"type":"string","maxLength":4000},"sexo":{"enum":["Femenino","Masculino","Otro"]},"nacimiento":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},"email":{"type":"string","maxLength":4000},"tension":{"type":"string","maxLength":4000},"pulso":{"type":"string","maxLength":4000},"frecuenciaRespiratoria":{"type":"string","maxLength":4000},"motivo":{"type":"string","maxLength":4000},"enfermedad":{"type":"string","maxLength":4000},"tratamientoMedico":{"type":"string","maxLength":4000},"hospitalizacion":{"type":"string","maxLength":4000},"alergias":{"type":"string","maxLength":4000},"hemorragia":{"type":"string","maxLength":4000},"desmayos":{"type":"string","maxLength":4000},"embarazo":{"type":"string","maxLength":4000},"sustancias":{"type":"string","maxLength":4000},"problemasDentales":{"type":"string","maxLength":4000},"cardiacos":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"tuberculosis":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"anemia":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"ictericia":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"asma":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"presion":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"diabetes":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"hepatitis":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"epilepsia":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"fiebreReumatica":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"traumatismo":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"sida":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"cirugias":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"gastrointestinales":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"transfusiones":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"artritis":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"renal":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"cancer":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"nervioso":{"enum":["Personal","Familiar","Personal y familiar","Sin antecedente"]},"labios":{"enum":["Normal","Atípico"]},"lengua":{"enum":["Normal","Atípico"]},"paladarDuro":{"enum":["Normal","Atípico"]},"paladarBlando":{"enum":["Normal","Atípico"]},"carrillos":{"enum":["Normal","Atípico"]},"pisoBoca":{"enum":["Normal","Atípico"]},"vestibulo":{"enum":["Normal","Atípico"]},"glandulas":{"enum":["Normal","Atípico"]},"caries":{"type":"string","pattern":"^[0-9]{1,4}$"},"cariesDolor":{"type":"string","pattern":"^[0-9]{1,4}$"},"ausentes":{"type":"string","pattern":"^[0-9]{1,4}$"},"restauraciones":{"type":"string","maxLength":4000},"higiene":{"type":"string","maxLength":4000},"periodonto":{"type":"string","maxLength":4000},"oclusion":{"type":"string","maxLength":4000},"inflamacion":{"enum":["Sí","No"]},"sarroSupra":{"enum":["Sí","No"]},"sarroInfra":{"enum":["Sí","No"]},"migracion":{"enum":["Sí","No"]},"bolsas":{"enum":["Sí","No"]},"calidadHigiene":{"enum":["Buena","Regular","Mala"]},"radiografia":{"type":"string","maxLength":4000},"diagnostico":{"type":"string","maxLength":4000},"plan":{"type":"string","maxLength":4000},"notas":{"type":"string","maxLength":4000},"observaciones":{"type":"string","maxLength":4000},"firmaPaciente":{"type":"string","maxLength":4000},"firmaOdontologo":{"type":"string","maxLength":4000}},"additionalProperties":false},"odontograma":{"type":"object","patternProperties":{"^([1-4][1-8]|[5-8][1-5])$":{"type":"object","properties":{"hallazgo":{"type":"string","maxLength":4000},"vestibular":{"type":"string","maxLength":4000},"lingual":{"type":"string","maxLength":4000},"mesial":{"type":"string","maxLength":4000},"distal":{"type":"string","maxLength":4000},"oclusal":{"type":"string","maxLength":4000},"tratamiento":{"type":"string","maxLength":4000},"presupuesto":{"type":"string","pattern":"^[0-9]{1,12}(\\.[0-9]{1,2})?$"}},"additionalProperties":false}},"additionalProperties":false},"evolucion":{"type":"array","maxItems":300,"items":{"type":"object","properties":{"fecha":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},"tratamiento":{"type":"string","maxLength":4000},"total":{"type":"string","pattern":"^[0-9]{1,12}(\\.[0-9]{1,2})?$"},"anticipo":{"type":"string","pattern":"^[0-9]{1,12}(\\.[0-9]{1,2})?$"},"resta":{"type":"string","pattern":"^[0-9]{1,12}(\\.[0-9]{1,2})?$"},"firma":{"type":"string","maxLength":4000},"abonos":{"type":"array","maxItems":100,"items":{"type":"object","required":["fecha","cantidad"],"additionalProperties":false,"properties":{"fecha":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},"cantidad":{"type":"string","pattern":"^[0-9]{1,12}(\\.[0-9]{1,2})?$"}}}}},"additionalProperties":false}}},"additionalProperties":false,"required":["id","nombre","telefono"]}$schema$::json,doc);
exception when datetime_field_overflow or invalid_datetime_format or invalid_text_representation or numeric_value_out_of_range then
  return false;
end $$;
revoke all on function clinic_private.valid_dental_record(jsonb) from public,anon,authenticated,service_role;
